"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[29402],{3331:(e,r,n)=>{n.d(r,{R:()=>o,x:()=>a});var i=n(36672);const t={},s=i.createContext(t);function o(e){const r=i.useContext(s);return i.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function a(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:o(e.components),i.createElement(s.Provider,{value:r},e.children)}},50240:(e,r,n)=>{n.r(r),n.d(r,{assets:()=>d,contentTitle:()=>a,default:()=>m,frontMatter:()=>o,metadata:()=>i,toc:()=>l});const i=JSON.parse('{"id":"2023/04/06","title":"2023-04-06","description":"Til minde om Bob Lee","source":"@site/i18n/da/docusaurus-plugin-content-docs/current/2023/04/06.md","sourceDirName":"2023/04","slug":"/2023/04/06","permalink":"/da/2023/04/06","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/da/docusaurus-plugin-content-docs//current/2023/04/06.md","tags":[],"version":"current","frontMatter":{"localized_date":"6. april 2023","top_news":"Til minde om Bob Lee"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-07","permalink":"/da/2023/04/07"},"next":{"title":"2023-04-05","permalink":"/da/2023/04/05"}}');var t=n(23420),s=n(3331);const o={localized_date:"6. april 2023",top_news:"Til minde om Bob Lee"},a="2023-04-06",d={},l=[{value:"Til minde om Bob Lee",id:"til-minde-om-bob-lee",level:2},{value:"Bob Lee, tidligere CTO for Square, er d\xf8d efter at v\xe6re blevet stukket ned i San Francisco",id:"bob-lee-tidligere-cto-for-square-er-d\xf8d-efter-at-v\xe6re-blevet-stukket-ned-i-san-francisco",level:2},{value:"Fort\xe6l iOS lader udbydere tilf\xf8je WiFi-netv\xe6rk, som du ikke kan forhindre i at deltage i",id:"fort\xe6l-ios-lader-udbydere-tilf\xf8je-wifi-netv\xe6rk-som-du-ikke-kan-forhindre-i-at-deltage-i",level:2},{value:"Deep Learning-fundamenter til stabil udbredelse",id:"deep-learning-fundamenter-til-stabil-udbredelse",level:2},{value:"CAN Injection: N\xf8glefri biltyveri",id:"can-injection-n\xf8glefri-biltyveri",level:2},{value:"Firefox-ingeni\xf8rer opdager en Windows Defender-fejl, der for\xe5rsager et h\xf8jt CPU-forbrug",id:"firefox-ingeni\xf8rer-opdager-en-windows-defender-fejl-der-for\xe5rsager-et-h\xf8jt-cpu-forbrug",level:2},{value:"Segment Anything Model (SAM) kan &quot;sk\xe6re&quot; ethvert objekt i et billede ud",id:"segment-anything-model-sam-kan-sk\xe6re-ethvert-objekt-i-et-billede-ud",level:2},{value:"Bitcoin whitepaper er gemt i alle kopier af macOS",id:"bitcoin-whitepaper-er-gemt-i-alle-kopier-af-macos",level:2},{value:"Tidligere Square CTO Bob Lee stukket ihjel i Downtown San Francisco",id:"tidligere-square-cto-bob-lee-stukket-ihjel-i-downtown-san-francisco",level:2},{value:"Argumentet for at forbyde b\xf8rn adgang til sociale medier",id:"argumentet-for-at-forbyde-b\xf8rn-adgang-til-sociale-medier",level:2},{value:"Dang har snart 65.535 karmapoint",id:"dang-har-snart-65535-karmapoint",level:2},{value:"Neurale netv\xe6rk: Zero to Hero",id:"neurale-netv\xe6rk-zero-to-hero",level:2},{value:"Et trick til at n\xe5 flow: Lad dit arbejde v\xe6re \xf8delagt",id:"et-trick-til-at-n\xe5-flow-lad-dit-arbejde-v\xe6re-\xf8delagt",level:2},{value:"Er RAM slettet f\xf8r brug i en anden LXC-container?",id:"er-ram-slettet-f\xf8r-brug-i-en-anden-lxc-container",level:2},{value:"Perspektiv: Open Source WebAssembly-Powered BI",id:"perspektiv-open-source-webassembly-powered-bi",level:2},{value:"Grid World",id:"grid-world",level:2},{value:"OpenAI Tokenizer",id:"openai-tokenizer",level:2},{value:"Tabloid - Programmeringssprog til Clickbait-overskrifter",id:"tabloid---programmeringssprog-til-clickbait-overskrifter",level:2},{value:"GPT4 simulerer en FTP-server p\xe5 ftp.disney.com",id:"gpt4-simulerer-en-ftp-server-p\xe5-ftpdisneycom",level:2},{value:"Brug af mmap til at g\xf8re LLaMA hurtigere at indl\xe6se",id:"brug-af-mmap-til-at-g\xf8re-llama-hurtigere-at-indl\xe6se",level:2}];function g(e){const r={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(r.header,{children:(0,t.jsx)(r.h1,{id:"2023-04-06",children:"2023-04-06"})}),"\n",(0,t.jsx)(r.h2,{id:"til-minde-om-bob-lee",children:"Til minde om Bob Lee"}),"\n",(0,t.jsx)(r.p,{children:"Teknologisamfundet s\xf8rger over tabet af Bob Lee, en velkendt person i branchen. Lee var en fortaler for Java, da han arbejdede for Google og Square, og han var kendt for sit arbejde med Guice-rammen til injektion af afh\xe6ngigheder. Han var ogs\xe5 medstifter af Android Alliance, et initiativ, der har til form\xe5l at fremme innovation i Android-\xf8kosystemet. Lees bidrag til den teknologiske verden var bredt anerkendt, og han vil blive savnet meget af sine kolleger og ligesindede. Mange har delt deres kondolence p\xe5 de sociale medier og mindet Lee som en mentor og ven, der altid tog sig tid til andre. Hvil i fred, Bob Lee."}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35457341",children:"Discussion Service"}),".\nBob Lee, medforfatter af Guice- og Java-bibliotekerne, der var kendt for sine tekniske f\xe6rdigheder, venlighed og ydmyghed, er g\xe5et bort. Hans d\xf8d har efterladt det tekniske samfund i sorg og har f\xe5et mange mennesker til at dele deres minder og anekdoter om ham. Lees arv af innovation og passion har inspireret mange, og hans bidrag til branchen vil blive savnet. Selv om nogle kommentarer var afvigende, delte de fleste positive tanker og oplevelser om Bob."]}),"\n",(0,t.jsx)(r.h2,{id:"bob-lee-tidligere-cto-for-square-er-d\xf8d-efter-at-v\xe6re-blevet-stukket-ned-i-san-francisco",children:"Bob Lee, tidligere CTO for Square, er d\xf8d efter at v\xe6re blevet stukket ned i San Francisco"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.sfgate.com/bayarea/article/mill-valley-man-killed-sf-stabbing-17878809.php",children:"Original"}),".\nBob Lee, skaberen af Cash App som Chief Technology Officer hos Square, blev identificeret som den mand, der blev dr\xe6bt i San Francisco p\xe5 grund af et knivstikkeri; begivenheden har chokeret tech-verdenen, hvor folk reagerede p\xe5 den pludselige nyhed. Politiet har ikke foretaget nogen anholdelser eller frigivet nogen oplysninger om mulige mist\xe6nkte. Lee var 43 \xe5r gammel, var grundl\xe6gger af Cash App og havde arbejdet som Chief Product Officer hos MobileCoin p\xe5 tidspunktet for sin d\xf8d."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35448899",children:"Discussion Service"}),".\nTidligere CTO for Square, Bob Lee, dr\xe6bt i San Francisco udl\xf8ser diskussion om kriminalitet og forvaltning. Kommentarer d\xe6kker rigdomsforskelle, hjeml\xf8shed, gentrificering og mulige l\xf8sninger. Diskussionen rejser udfordringer om politiske systemer og up\xe5lidelige kriminalitetsstatistikker i amerikanske byer. Brugerne diskuterer potentielle \xe5rsager til kriminalitet, herunder masseindvandring, ulighed i velstand, p\xe5virkede retssystemer og politiets manglende reaktionsevne. Det er ikke nyttigt at sammenligne kriminalitet mellem forskellige lande eller kulturer. Problemet med kriminalitet er komplekst og skyldes ikke en enkelt faktor."]}),"\n",(0,t.jsx)(r.h2,{id:"fort\xe6l-ios-lader-udbydere-tilf\xf8je-wifi-netv\xe6rk-som-du-ikke-kan-forhindre-i-at-deltage-i",children:"Fort\xe6l iOS lader udbydere tilf\xf8je WiFi-netv\xe6rk, som du ikke kan forhindre i at deltage i"}),"\n",(0,t.jsx)(r.p,{children:'Operativsystemet iOS giver udbyderne mulighed for at tilf\xf8je WiFi-netv\xe6rk, som brugerne ikke kan v\xe6lge at afvise at deltage i. Denne funktion v\xe6kker bekymring blandt iPhone-brugere, der har begr\xe6nsede dataabonnementer eller er bekymrede for privatlivets fred. Funktionen er beregnet til at hj\xe6lpe udbyderne med at oprette WiFi-hotspots, men den giver dem ogs\xe5 mulighed for at tilf\xf8je offentlige WiFi-netv\xe6rk, som brugerne ubevidst opretter forbindelse til, hvilket kan indsamle f\xf8lsomme data. Brugerne har begr\xe6nsede muligheder for at deaktivere funktionen, herunder at de helt kan deaktivere WiFi eller v\xe6lge at "glemme dette netv\xe6rk", hver gang de st\xf8der p\xe5 det. Nogle brugere opfordrer Apple til at tilf\xf8je mere kontrol over denne funktion, mens andre foresl\xe5r, at de bruger en VPN til at beskytte deres data.'}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35447486",children:"Discussion Service"}),".\niOS 16.4 g\xf8r det muligt for udbydere at tilf\xf8je administrerede netv\xe6rk til enheder, s\xe6nke mobilomkostningerne og forhindre deaktivering af automatisk tilslutning, uden at der p\xe5 nuv\xe6rende tidspunkt er nogen anden m\xe5de at fjerne disse netv\xe6rk p\xe5 end at nulstille netv\xe6rksindstillingerne. Brugere rapporterer om T-Mobile, der stj\xe6ler data, og om Wingman-netv\xe6rk under flyvninger, der ikke slukkes, og udtrykker chok over, at udbyderne dikterer WiFi-forbindelser uden brugerens mulighed for at g\xf8re noget ved det. Der opst\xe5r en debat om, hvordan man kan f\xe5 fuldst\xe6ndig kontrol over enheden, og nogle brugere anbefaler GrapheneOS til sikkerhedsopdateringer. WiFi-hotspots hos udbyderne kritiseres for at afbryde forbindelserne til lokale enheder, mens nogle finder funktionen nyttig i overfyldte omr\xe5der."]}),"\n",(0,t.jsx)(r.h2,{id:"deep-learning-fundamenter-til-stabil-udbredelse",children:"Deep Learning-fundamenter til stabil udbredelse"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://course.fast.ai/Lessons/part2.html",children:"Original"}),'.\n"Practical Deep Learning for Coders - Part 2" er et kursus best\xe5ende af over 30 timers videoindhold, der omfatter d\xe6kning af Stable Diffusion-algoritmen fra bunden, i t\xe6t samarbejde med eksperter fra Stable.ai og Hugging Face. Kurset giver en rigor\xf8s d\xe6kning af de nyeste teknikker og g\xe5r endda ud over, hvad Stable Diffusion omfatter, hvilket g\xf8r det til et godt l\xe6ringsm\xe5l af mange grunde, men for at f\xe5 mest muligt ud af dette kursus b\xf8r du v\xe6re en rimelig sikker deep learning-praktiker. I l\xf8bet af kurset vil vi udforske diffusionsmetoder, implementere vores egne modeller fra bunden, mestre Python-koncepter og PyTorch til at implementere vores modeller. Vi vil d\xe6kke diffusionsfundamenter, deep learning-optimizers, Python-koncepter, grundl\xe6ggende fundamenter, pseudo-tilf\xe6ldig talgenerering, neurale netv\xe6rksarkitekturer, generative arkitekturer, transformatorer og tr\xe6ning med blandet pr\xe6cision.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35449831",children:"Discussion Service"}),".\n'Deep Learning Foundations to Stable Diffusion' udforsker moderne generativ modellering, mens nogle anbefaler at fokusere p\xe5 markedsf\xf8ring. Fast.ai's kursus i deep learning skaber en programmeringsramme fra bunden og anbefales til alle interesserede. Der er en debat om de potentielle farer ved avanceret AI og betydningen af regulering og etiske overvejelser. Kommentatorer foresl\xe5r at forbyde AI-produktion, men det er ikke en langsigtet l\xf8sning, medmindre alle lande g\xf8r det. FastAI's kursus har ingen politisk eller religi\xf8st forudindtagede udsagn, og indholdet anses for at v\xe6re i top. Kurset er tilg\xe6ngeligt for alle med grundl\xe6ggende gymnasiematematik og d\xe6kker avancerede begreber."]}),"\n",(0,t.jsx)(r.h2,{id:"can-injection-n\xf8glefri-biltyveri",children:"CAN Injection: N\xf8glefri biltyveri"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://kentindell.github.io/2023/04/03/can-injection/",children:"Original"}),".\nBiltyve bruger en ny teknik kaldet CAN-injektion til at omg\xe5 smarte n\xf8glesystemer i moderne biler ved at udnytte s\xe5rbarheder i CAN-bus-kommunikationsprotokollen. Sofistikerede bilsikkerhedssystemer, herunder startsp\xe6rreanordninger, er blevet s\xe5rbare. Tyvene bruger en anordning kaldet CAN Injector til at stj\xe6le biler uden n\xf8gle ved at injicere falske meddelelser i bilens interne kommunikationssystem. Enheden koster 10 USD og indeholder en PIC18F-chip, forprogrammeret firmware, en transceiver og et ekstra kredsl\xf8b. En hurtig rettelse eller en kryptografisk besked kan besejre CAN Injector. Ian Haken skitserer flere m\xe5der, hvorp\xe5 bilproducenter kan hj\xe6lpe med at sikre biler, men kriminel udnyttelse af teknikken er udbredt. Det er et problem, der omfatter hele industrien, og som kr\xe6ver en opdatering af ECU-softwaren for at besejre tyvene."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35452963",children:"Discussion Service"}),".\nEn teknik til tyveri af n\xf8glefri biler, kendt som CAN Injection, blev fremh\xe6vet p\xe5 Hacker News. Forbrugerne b\xf8r v\xe6re forsigtige med at kryptere eller signere CAN Bus, da det kan begr\xe6nse tredjepartsdiagnosev\xe6rkt\xf8jer og dermed \xf8ge reparationsomkostningerne. CAN-bussen styrer flere k\xf8ret\xf8jsfunktioner, og k\xf8ret\xf8jsfabrikanterne optimerer omkostningerne hensynsl\xf8st. Bilproducenterne har juridiske krav om at adskille sig fra forhandlerne, men nogle kommentarer kritiserer deres overholdelse af lovens \xe5nd. F\xf8rsteklasses bilm\xe6rker anvender forskellige sikkerhedsforanstaltninger for at forhindre hacking af biler, herunder startsp\xe6rrer med passende kryptografiske protokoller til autentificering af start- og frigivelsesmeddelelser og signerede CAN/FlexRay/Ethernet-rammer for at forhindre efterligning af meddelelser. Billige biler er et m\xe5l for hackere, da de er lette at stj\xe6le, mens dyre biler er m\xe5l for voldelige tyverier. Den udnyttelse, der beskrives i artiklen, kan anvendes p\xe5 n\xe6sten alle ikke-tilsluttede k\xf8ret\xf8jer, der er fremstillet i det seneste \xe5rti. CAN-bussen anvendes i kritiske systemer, f.eks. inden for luftfart og bilindustrien, fordi den er let at koble sammen og er omkostningseffektiv."]}),"\n",(0,t.jsx)(r.h2,{id:"firefox-ingeni\xf8rer-opdager-en-windows-defender-fejl-der-for\xe5rsager-et-h\xf8jt-cpu-forbrug",children:"Firefox-ingeni\xf8rer opdager en Windows Defender-fejl, der for\xe5rsager et h\xf8jt CPU-forbrug"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://bugzilla.mozilla.org/show_bug.cgi?id=1441918#c82",children:"Original"}),".\nN/A (Denne tekst er ikke relateret til emnet)."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35458746",children:"Discussion Service"}),".\nFirefox-ingeni\xf8rer har fundet en Windows Defender-fejl, der for\xe5rsager CPU-forbrug p\xe5 Mozillas browser. Microsoft frigiver en patch for at rette dette. Andre AV-produkter kan ogs\xe5 for\xe5rsage problemer med CPU-forbrug. Firefox foretager flere systemkald end Chrome af sikkerhedshensyn. En sammenligning viser, at Firefox klarer sig hurtigere end Chrome i nogle tests. Eksperter diskuterer begr\xe6nsningerne i Defender, foresl\xe5r sandboxing og hardware-MFA. Brugere diskuterer effektiviteten af Defender i forhold til AV-software fra tredjeparter. Nogle brugere rapporterer om problemer med Defender, der for\xe5rsager langsom adgang til filsystemet."]}),"\n",(0,t.jsx)(r.h2,{id:"segment-anything-model-sam-kan-sk\xe6re-ethvert-objekt-i-et-billede-ud",children:'Segment Anything Model (SAM) kan "sk\xe6re" ethvert objekt i et billede ud'}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://segment-anything.com/",children:"Original"}),".\nSegment Anything Model (SAM), der er udviklet af Meta AI, kan isolere ethvert objekt i et billede med stor n\xf8jagtighed. Den kan identificere og segmentere objekter med succes, selv n\xe5r de er delvist synlige eller tild\xe6kkede. SAM forbedrer tidligere udviklede modeller, der var baseret p\xe5 placeringsindikationer eller fremtr\xe6dende objekter. I stedet for at bruge disse stikord anvender SAM meta-l\xe6ring, der udnytter en eksisterende models indl\xe6ring, for at kunne registrere sm\xe5, forudindtagede datas\xe6t eller usynlige objekter. SAM kan anvendes til praktiske anvendelser, f.eks. billedredigering, samt til forskning inden for computervision."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35455566",children:"Discussion Service"}),".\nMeta AI's SAM g\xf8r det muligt at generere masker i realtid for at \"sk\xe6re\" ethvert objekt ud af et billede. Modellens licensering og imponerende inferencing-funktioner kan g\xf8re den popul\xe6r blandt teknologieksperter. Problemer omfatter langsommere hastighed med RTX 2080ti 11GB-modellen og begr\xe6nset pr\xe6cision med gennemsigtige objekter. Nogle ser Meta AI's udgivelsesstrategi som en del af et AR-adoptionspush. Brugere roser SAM's omkostningsreduktion for dataannotation, men kritiserer hastigheden og sammenligner den med iOS. Udviklingen kan ogs\xe5 have potentiel sikkerhedskameraapplikation og AdobeAI-integration."]}),"\n",(0,t.jsx)(r.h2,{id:"bitcoin-whitepaper-er-gemt-i-alle-kopier-af-macos",children:"Bitcoin whitepaper er gemt i alle kopier af macOS"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://waxy.org/2023/04/the-bitcoin-whitepaper-is-hidden-in-every-modern-copy-of-macos/",children:"Original"}),'.\nEn PDF-kopi af Satoshi Nakamotos Bitcoin-whitepaper er blevet opdaget i alle moderne kopier af macOS siden Mojave i 2018 og kan tilg\xe5s via et eksempeldokument i v\xe6rkt\xf8jet Image Capture. Whitepaperet bruges som et eksempeldokument til en enhed kaldet "Virtual Scanner II", som enten er skjult eller ikke er installeret for alle som standard. \xc5rsagen til dets medtagelse er stadig uklar, men det kan have v\xe6ret en praktisk og letv\xe6gts flersidet PDF-fil til testform\xe5l. Der er meget f\xe5 oplysninger tilg\xe6ngelige online om Virtual Scanner II eller whitepaperets medtagelse i macOS.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35461011",children:"Discussion Service"}),".\nBitcoin-hvidbogen er skjult i alle macOS-kopier siden 2019; der spekuleres i, hvorfor den er inkluderet, og brugere advarer mod minedrift p\xe5 iPhones. Hashsummen svarer til den oprindelige version, men teorierne varierer om hvorfor den er inkluderet. Der er kommet klager over godkendelse af et Ponzi-arrangement, men brugerne pr\xe6ciserer, at det er skjult. Apple har m\xe5ske inkluderet det for nemheds skyld, men indl\xe6gget skaber en dialog om Bitcoin's indvirkning. Brugere kommenterer p\xe5 det billede, der er brugt i en artikel, PDF-filst\xf8rrelsen og om teknologi, der mister sin kunstneriske sjov."]}),"\n",(0,t.jsx)(r.h2,{id:"tidligere-square-cto-bob-lee-stukket-ihjel-i-downtown-san-francisco",children:"Tidligere Square CTO Bob Lee stukket ihjel i Downtown San Francisco"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://sfstandard.com/criminal-justice/san-francisco-stabbing-victim-bob-lee-former-cto-square-mobilecoin/",children:"Original"}),".\nDen tidligere Square CTO Bob Lee blev if\xf8lge The Standard stukket ihjel i Downtown San Francisco. Lee var Chief Product Officer for MobileCoin, et krypto-firma i San Francisco, og et elsket medlem af Bay Area softwareudvikling og teknologif\xe6llesskaber. SFPD har ikke frigivet yderligere detaljer eller offerets identitet og anmoder om \xf8jenvidner og videooptagelser til deres efterforskning. San Francisco har pr. 2. april oplevet 12 drab, hvilket er to flere end i samme periode sidste \xe5r. The Standard d\xe6kker vigtige historier, herunder strafferetlige sp\xf8rgsm\xe5l i San Francisco, og leverer nyhedsbreve og et omfattende overblik over San Franciscos politik og kultur."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35452426",children:"Discussion Service"}),".\nTidligere Square CTO Bob Lee stukket ihjel i San Francisco; kommentarer henviser til nye detaljer."]}),"\n",(0,t.jsx)(r.h2,{id:"argumentet-for-at-forbyde-b\xf8rn-adgang-til-sociale-medier",children:"Argumentet for at forbyde b\xf8rn adgang til sociale medier"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.newyorker.com/news/our-columnists/the-case-for-banning-children-from-social-media",children:"Original"}),".\nDebatten om at forbyde b\xf8rn fra sociale medier er i gang p\xe5 grund af bekymringer om afh\xe6ngighed og negativitet. Nogle lovforslag er blevet vedtaget for at begr\xe6nse mindre\xe5riges adgang til sociale medier og fjerne vanedannende funktioner, men dette rejser konsekvenser for borgerrettighederne og begr\xe6nser adgangen til nyheder og forskellige perspektiver, hvilket rejser sp\xf8rgsm\xe5let om, hvordan sociale medier b\xf8r behandles. Selv om domstolene har afvist online-beskyttelser af hensyn til b\xf8rns sikkerhed, er der potentielle konflikter med rettighederne i henhold til det f\xf8rste till\xe6g til forfatnings\xe6ndringen ved at skabe budskaber mod afh\xe6ngighed og juridiske begr\xe6nsninger, og for\xe6ldre kan blive n\xf8dt til at ty til fysisk fjernelse af sk\xe6rme. Beskyttelse af b\xf8rn p\xe5 nettet er en politisk og kulturel debat, som ikke giver megen tillid til regeringens evne til at regulere virksomheder inden for sociale medier."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35447588",children:"Discussion Service"}),".\nI en artikel anbefales det at forbyde sociale medier for unge under 18 \xe5r p\xe5 grund af den potentielle narkotikalignende afh\xe6ngighed; det er vanskeligt at regulere s\xe5dant indhold. En debat om definitionen og indflydelsen af reklamer rettet mod b\xf8rn giver anledning til bekymring over reguleringen af reklamer. De sociale mediers skadelige virkninger p\xe5 den mentale sundhed og den personlige udvikling tages op, hvilket giver anledning til forslag om at forbyde virksomheders sociale medier og algoritmiske feeds. Et generelt forbud mod sociale medier anses ikke for at v\xe6re l\xf8sningen; der er behov for en nuanceret tilgang. Discussion Service-brugere diskuterer effektive m\xe5der at begr\xe6nse sk\xe6rmtiden og bek\xe6mpe de negative virkninger p\xe5. Debatten drejer sig om at finde en balance mellem individuel frihed og samfundsm\xe6ssigt ansvar. Bekymringer om kontrol med sociale medier og dopaminfrigivelse i hjernen giver anledning til diskussioner om forbud mod algoritmestyrede sociale medier. Gennemf\xf8rlighed og potentiel kr\xe6nkelse af privatlivets fred fremh\xe6ves som bekymringer i forbindelse med obligatorisk ID-kontrol af konti p\xe5 sociale medier. Der dr\xf8ftes ingen ny teknologi eller st\xf8rre udgivelser."]}),"\n",(0,t.jsx)(r.h2,{id:"dang-har-snart-65535-karmapoint",children:"Dang har snart 65.535 karmapoint"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://news.ycombinator.com/user?id=dang",children:"Original"}),".\nDiscussion Service-brugeren 'dang' forventes snart at n\xe5 65.535 karmapoint, hvilket er den maksimale gr\xe6nse p\xe5 grund af systemets brug af et 16-bit heltal med fortegn."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35460732",children:"Discussion Service"}),".\nDaniel Gackle, AKA Dang, er ved at n\xe5 65.535 karmapoint. Kommentarsektionen er fyldt med ros til Dangs arbejde. Brugere spekulerer i, om karma vil rulle over & diskuterer at skifte til 32-bit int. Der s\xe6ttes sp\xf8rgsm\xe5lstegn ved moderationsstilen og Y Combinators involvering. Opn\xe5else af h\xf8j karma ses som en m\xe5de at vise anerkendelse for Dangs arbejde. Hvis man n\xe5r h\xf8jere karma-milep\xe6le, kan man f\xe5 yderligere muligheder p\xe5 Discussion Service, f.eks. upvoting/downvoting."]}),"\n",(0,t.jsx)(r.h2,{id:"neurale-netv\xe6rk-zero-to-hero",children:"Neurale netv\xe6rk: Zero to Hero"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://karpathy.ai/zero-to-hero.html",children:"Original"}),'.\nKurset "Neural Networks: Zero to Hero" af Andrej Karpathy l\xe6rer at opbygge neurale netv\xe6rk fra bunden i kode. Kurset begynder med de grundl\xe6ggende principper for backpropagation og g\xe5r videre til moderne dybe neurale netv\xe6rk som GPT. Kurset fokuserer p\xe5 sprogmodeller, da de er et glimrende sted at l\xe6re deep learning. Foruds\xe6tninger omfatter solid programmering og matematik p\xe5 intro-niveau. Kurset omfatter opbygning af micrograd, makemore, en MLP og dykning i nogle af de interne aspekter af MLP\'er. At blive en Backprop Ninja og opbygning af WaveNet er ogs\xe5 omfattet. Kurset kulminerer med opbygning af GPT. Videoerne giver en trinvis forklaring og fokuserer p\xe5 at opbygge kompetence og intuition omkring hvordan neurale net optimeres. Kurset anbefaler, at seerne ser de tidligere makemore-videoer for at v\xe6re fortrolig med den autoregressive sprogmodelleringsramme og det grundl\xe6ggende i tensorer og PyTorch nn.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35459031",children:"Discussion Service"}),".\nAndrej Karpathys \"Neural Networks: Zero to Hero'-kursus opn\xe5r over 300 point p\xe5 Hacker News p\xe5 6 timer. Discussion Service-brugere roser hans undervisningsstil og anbefaler, at man koder med efter at have set videoerne. Hans peer-ledede ML-kursus f\xe5r positiv feedback, selv om han ikke n\xe6vner det. Python-specifik syntaks i videoerne kunne udfordre nogle brugere. En diskussion evaluerer kursets v\xe6gt p\xe5 logistisk regression og perceptron i en diskussion. Deltagerne fandt kurset let at forst\xe5 og anbefaler andre kurser for begyndere. Nogle brugere s\xe6tter sp\xf8rgsm\xe5lstegn ved webudvikleres minimumsviden, og en bruger har en teori om forbindelsen mellem ML og Hopf-algebra."]}),"\n",(0,t.jsx)(r.h2,{id:"et-trick-til-at-n\xe5-flow-lad-dit-arbejde-v\xe6re-\xf8delagt",children:"Et trick til at n\xe5 flow: Lad dit arbejde v\xe6re \xf8delagt"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://census.dev/blog/an-on-ramp-to-flow",children:"Original"}),'.\nArtiklen diskuterer vanskeligheden ved at komme ind i en tilstand af "flow" i tekniske opgaver og giver et trick til at komme ind i flow igen. Forfatteren foresl\xe5r, at man efterlader sit arbejde i en tilstand, der tydeligvis er \xf8delagt, men som er let at reparere, f\xf8r man g\xe5r v\xe6k. Dette giver et klart udgangspunkt, n\xe5r man vender tilbage til arbejdet, hvilket skaber momentum og tillid. Artiklen erkender, at denne fremgangsm\xe5de m\xe5ske ikke er universel eller anvendelig i teamsammenh\xe6nge, men opfordrer til at give feedback p\xe5 andre tricks. Der er ogs\xe5 en kort omtale af Census Engineering og jobmuligheder.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35456059",children:"Discussion Service"}),'.\nDiscussion Service-brugere deler tips til at opn\xe5 flowtilstand ved at lade arbejdet st\xe5 uf\xe6rdigt, herunder "park\xe9r med front mod nedadg\xe5ende bakke"-metoden. En ingeni\xf8rdirekt\xf8r implementerede at forlade arbejdet inden kl. 18.00 for at undg\xe5 udbr\xe6ndthed, men afsluttede det p\xe5 grund af presenteeisme. Brugerne diskuterer fordelene og risiciene ved strenge tidsregler og \xe6ndring af arbejdskulturen. Nogle deler produktivitetstips, f.eks. at skrive n\xe6ste trin ned og praktisere TDD. At efterlade kode i en "\xf8delagt" tilstand kan hj\xe6lpe med at genoptage senere, men det har blandede resultater.']}),"\n",(0,t.jsx)(r.h2,{id:"er-ram-slettet-f\xf8r-brug-i-en-anden-lxc-container",children:"Er RAM slettet f\xf8r brug i en anden LXC-container?"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://security.stackexchange.com/questions/269507/is-ram-wiped-before-use-in-another-lxc-container",children:"Original"}),".\nEt indl\xe6g p\xe5 Information Security Stack Exchange sp\xf8rger, om RAM t\xf8rres af f\xf8r brug i en anden LXC-container, hvilket f\xf8rer til en diskussion om RAM-overprovisioning i LXC, hvor en bruger kommenterer, at hukommelse allokeret til en tidligere proces i en container ryddes. Et indl\xe6g p\xe5 Hacker News dykker yderligere ned og diskuterer delte biblioteker og beskyttelse af brugernes navnerum, og et svar pr\xe6ciserer, at siderne slettes f\xf8r allokering, at overprovisionering ikke for\xe5rsager deling, og at LXC-hukommelse allokeres til processer via navnerum, men at processer er adskilt fra v\xe6rtsressourcer. Endelig bem\xe6rkes det, at glibc-baseret hukommelsesstyring ikke indeb\xe6rer oprydning, og at frie sider kan indeholde data."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35451863",children:"Discussion Service"}),".\nBrugere p\xe5 Hacker News diskuterede effektiviteten og n\xf8dvendigheden af automatisk hukommelsesnullering i Linux, og nogle foreslog alternative metoder til at rydde ubrugt hukommelse. En bruger p\xe5pegede, at problemet ligger i udformningen af UNIX' fork()-systemopkald, og at mange hukommelsesintensive programmer stadig k\xe6mper med OOM-problemer. Andre kommentarer omhandler forskellene mellem overcommit- og non-overcommit-hukommelsesallokering i Linux og betydningen af at s\xe6tte gr\xe6nser. Artiklen giver nuancerede perspektiver p\xe5 Linux-hukommelsesallokering og er rettet mod eksperter p\xe5 omr\xe5det."]}),"\n",(0,t.jsx)(r.h2,{id:"perspektiv-open-source-webassembly-powered-bi",children:"Perspektiv: Open Source WebAssembly-Powered BI"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://perspective.finos.org/",children:"Original"}),".\nPerspective er en interaktiv analyse- og datavisualiseringskomponent, der er designet til streaming og store datas\xe6t med konfigurerbare rapporter, dashboards og notesb\xf8ger. Den har en hukommelseeffektiv streaming foresp\xf8rgselsmotor i C++ og Python og en brugergr\xe6nseflade pakket som et brugerdefineret element drevet af WebAssembly eller WebSocket. Brugergr\xe6nsefladen omfatter interaktive dashboards, der kan integreres i enhver webapplikationsramme. Perspective.js er afh\xe6ngig af WebAssembly og Apache Arrow for at opn\xe5 desktoplignende ydeevne i browseren. PerspectivePython implementerer Perspective API direkte i Python til forskning eller produktion. Der er virtualiserede og skalerbare widgets, og projektet er tilg\xe6ngeligt p\xe5 GitHub med bruger- og programm\xf8rvejledninger."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35455850",children:"Discussion Service"}),".\nOpen-source WebAssembly-drevet BI-v\xe6rkt\xf8j Perspective roses for kraftig funktionalitet, trods problemer med ydeevnen: l\xf8sninger foresl\xe5s bl.a. ved hj\xe6lp af en mere letv\xe6gtsl\xf8sning. Producenterne af Perspective arbejder p\xe5 at forbedre ydeevnen og mobilkompatibiliteten. Der er rejst visse bekymringer om Firefox-underst\xf8ttelse og tilg\xe6ngelighed/tilg\xe6ngelighed/ikke-tastaturvenligt design. Sciter-begr\xe6nsninger blev dr\xf8ftet, Tauri-biblioteker blev set som potentielt nyttige. Der er behov for forbedringer af ydeevnen for Perspective-projektet."]}),"\n",(0,t.jsx)(r.h2,{id:"grid-world",children:"Grid World"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://alex.miller.garden/grid-world/",children:"Original"}),'.\nAlexander Millers "Grid World" udforsker den rolle, som gitteret har spillet i hans liv fra barndommen til voksenalderen, herunder dets betydning for teknologi, kunst og navigation. Artiklen ber\xf8rer den magt, som gitter har i forbindelse med kortl\xe6gning og kontrol af rummet, som det ses i spil som Battleship og Chess. Gitteret bliver et centralt omdrejningspunkt, der forbinder Millers personlige erfaringer og viser, hvordan det bliver en del af vores liv. Miller skabte gitteret til The HTML Review i 2023.']}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35455770",children:"Discussion Service"}),".\nDiscussion Service-brugere er fascineret af Grid Worlds us\xe6dvanlige mesterskab og h\xe5ndv\xe6rk inden for webdesign og -udvikling og dens indvirkning p\xe5 opfattelsen. Artiklen udforsker gridets understruktur til vores erindringer og verden, med ledsagende pixel art visuals. Kommentarer bem\xe6rker forbindelsen til neurovidenskab med gridceller, mens de rejser kritik af rationalisering og gridets t\xe6ppe p\xe5 naturen. En bruger finder det sv\xe6rt at perfektionere de visuelle designaspekter af sit personlige projekt. Brugere diskuterer gitterm\xf8nstre i Queens og historien bag gitterm\xf8nstrene. En Discussion Service-bruger deler sin indsigt i NYC's gadenetters overensstemmelse. En bordlignende dekoration genererer svagt oplyste messesale, mens den udvikler sig gennem tiden, bygget med almindeligt javascript uden biblioteker for sjov teknisk \xf8velse."]}),"\n",(0,t.jsx)(r.h2,{id:"openai-tokenizer",children:"OpenAI Tokenizer"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://platform.openai.com/tokenizer",children:"Original"}),".\nOpenAI API er en teknologi, der kr\xe6ver, at JavaScript er aktiveret."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35453400",children:"Discussion Service"}),".\nOpenAI har frigivet en ny tokenizer for bedre at forst\xe5 GPT-modeller. Tokenizeren opdeler tekst i underordsenheder for effektiv behandling, men de mangler iboende betydning. Discussion Service-brugere diskuterer v\xe6rkt\xf8jets begr\xe6nsninger s\xe5som gruppering baseret p\xe5 mellemrum og behandlinger af kapitalisering. Kodninger, der er oprettet ved hj\xe6lp af bytepar-kodning, er ofte ikke velegnede til underrepr\xe6senterede sprog. OpenAI opkr\xe6ver gebyrer pr. token p\xe5 grund af modellens tokenbaserede drift."]}),"\n",(0,t.jsx)(r.h2,{id:"tabloid---programmeringssprog-til-clickbait-overskrifter",children:"Tabloid - Programmeringssprog til Clickbait-overskrifter"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://tabloid-thesephist.vercel.app/",children:"Original"}),".\nTabloid er et nyt programmeringssprog, der er skabt til at generere latterlige og klikv\xe6rdige overskrifter, der ligner dem, der ses i tabloider. Sproget bruger en kombination af naturlig sprogbehandling, maskinl\xe6ring og crowd-sourcing til at skabe overskrifter med clickbaity-sproglige m\xf8nstre. Det er et sjovt og underholdende sprog, der ikke tjener noget egentligt form\xe5l, men det er et glimrende eksempel p\xe5, hvordan programmering kan v\xe6re b\xe5de nyttigt og morsomt. Skaberen af Tabloid har planer om at bruge det til at skabe en platform, der giver alle mulighed for at skabe deres clickbait-overskrifter. Discussion Service-brugere finder dette v\xe6rkt\xf8j interessant og en nyttig m\xe5de at forst\xe5 naturlig sprogbehandling p\xe5."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35447580",children:"Discussion Service"}),'.\nEt nyligt projekt p\xe5 Hacker News kaldet Tabloid - The Clickbait Headline Programming Language. Projektet er fascinerende, skrevet af en forfatter, der h\xe6vder at have skrevet andre sprog, som nok er mere nyttige. En Discussion Service-bruger postede et program i Tabloid, der tager fem tal og returnerer produktet af de tre f\xf8rste tal plus produktet af de to sidste. Forfatteren er en person, der har sendt mange interessante projekter af sted, og som endda har brugt Oak til at bygge en masse personlig softwareinfrastruktur, blandt andet. En anden Discussion Service-bruger kommenterede, at det er mest levedygtigt for enlige udviklere at skrive alting fra bunden, men ikke for teams, hvor det er bedre at g\xe5 med "kedeligt".']}),"\n",(0,t.jsx)(r.h2,{id:"gpt4-simulerer-en-ftp-server-p\xe5-ftpdisneycom",children:"GPT4 simulerer en FTP-server p\xe5 ftp.disney.com"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://www.filestash.app/2023/04/01/chat-gpt-acting-as-a-ftp-server/",children:"Original"}),".\nChat GPT-4 er dygtig til at simulere en FTP-server for Disney, idet den bruger det grundl\xe6ggende ftp cli-v\xe6rkt\xf8j og kommer med prompter til at udf\xf8re kommandoer som en rigtig bruger ville g\xf8re det. Den simulerede server indeholder eksklusivt Disney-indhold i mapper som film, soundtracks og wallpapers, og GPT-4 viser sig at v\xe6re i stand til at navigere i lokale og eksterne filsystemer. Den nye teknologi klarer sig godt, overg\xe5r forventningerne og viser sin evne til at skabe overbevisende indhold for Disney-entusiaster. I artiklen antydes fremtidige anvendelsesmuligheder for GPT-4 i kodefortolker-plugins, der giver adgang til opdigtede servere fra FTP-klienter."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35450315",children:"Discussion Service"}),'.\nEn artikel p\xe5 Hacker News omhandler GPT4, der simulerer en FTP-server p\xe5 ftp.disney.com. Brugerne diskuterer, hvorvidt dette kan betragtes som "hallucination", p\xe5 trods af at AI kan simulere eller "hallucinere". Pr\xe6cisionen af AI-genererede svar og opfattelsen af disse output som "hallucinationer" er ogs\xe5 punkter, der diskuteres. Andre emner, der diskuteres, omfatter: potentialet for at selvgenererede film eller tv-shows er v\xe6rdil\xf8se, den rolle latent rum og sprog spiller i LLM\'er, teknologiens indvirkning p\xe5 samfundet og begr\xe6nsninger i de nuv\xe6rende AI-kapaciteter. Nogle brugere advarer mod at overfortolke AI\'s evner og bem\xe6rker, at dens begr\xe6nsninger ofte overses.']}),"\n",(0,t.jsx)(r.h2,{id:"brug-af-mmap-til-at-g\xf8re-llama-hurtigere-at-indl\xe6se",children:"Brug af mmap til at g\xf8re LLaMA hurtigere at indl\xe6se"}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"https://justine.lol/mmap/",children:"Original"}),".\nLLaMA bruger mmap() til at indl\xe6se modeller 100x hurtigere, \xf8ger RAM-stabiliteten og g\xf8r det muligt at k\xf8re flere processer samtidig. Linux-brugere f\xe5r 100x forbedring, mens Windows og MacOS f\xe5r 10x. Den nye mmap() loader er nu tilg\xe6ngelig p\xe5 GitHub under MIT-licens. Den anonyme samarbejdspartner @Slaren tilf\xf8jede mmap()-underst\xf8ttelse til LLaMA-7B, hvilket giver \xf8jeblikkelige indl\xe6sningstider uden \xe6ndring af filformatet. Det nye filformat justerer tensorer p\xe5 en 32-byte-gr\xe6nse. Indl\xe6gget udforsker potentielle forbedringer i diskudnyttelse og ydelsesforstyrrelser. Justine Tunney skriver om Twitter og Github i standardv\xe6rkt\xf8jer, der henvender sig til eksperter p\xe5 omr\xe5det. Det er klart og koncist, uden fordomme eller politiske eller religi\xf8se udtalelser. En Discussion Service-bruger kommenterer, at Tunneys indl\xe6g er en god ressource til l\xe6ring."]}),"\n",(0,t.jsxs)(r.p,{children:[(0,t.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35455930",children:"Discussion Service"}),".\nBrug af mmap til at f\xe5 LLaMA til at indl\xe6se hurtigere er det prim\xe6re fokus i artiklen, p\xe5 trods af dramatik omkring tilskrivning og tekniske sp\xf8rgsm\xe5l i kommentarfeltet. Fordelene og ulemperne ved mmap diskuteres, ligesom de tekniske fordele ved Facebooks LLaMA.cpp diskuteres. Brugere diskuterer nytten af LLaMA's \xe6ndringer og fordele og ulemper ved forskellige funktioner, hvilket giver v\xe6rdifuld indsigt for teknisk kyndige l\xe6sere, der er interesseret i at l\xe6re mere om AI og modelimplementering. Indl\xe6gget fremh\xe6ver en systemteknisk tilgang til et problem og en tendens, der involverer propriet\xe6r kode i biblioteker, hvilket genererer diskussion om brugen af Huge Pages og vanskeligheden ved at l\xf8se IO-flaskehalse. Den revolutionerende forbedring af ydeevnen ved hj\xe6lp af mmap har fanget opm\xe6rksomheden hos eksperter p\xe5 omr\xe5det."]})]})}function m(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,t.jsx)(r,{...e,children:(0,t.jsx)(g,{...e})}):g(e)}}}]);